 "content": "def transform(grid):
    """Expand a single horizontal seed into a downward V with diagonal stripes."""
    n = len(grid[0])
    seed = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        # The seed's two arms spread down-left and down-right.
        for c in (seed - r, seed + r):
            if 0 <= c < n:
                out[r][c] = 2
        # Fill every fourth down-right diagonal strictly inside the V.
        for c in range(n):
            if abs(c - seed) < r and (c - r - seed) % 4 == 0:
                out[r][c] = 1
    return out
